  Object.assign(state,{displayName:'小满',uNicknameDraft:'小满',uNicknameError:'',uAttachmentIndex:0,uAttachmentBill:1,uAttachmentCount:0,uAvatarImage:null,uAvatarCapture:false});
  const uProfileBeeMarkup=__PROFILE_BEE_MARKUP__;
  const uAvatarExample='data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160" viewBox="0 0 160 160"><rect width="160" height="160" fill="#dce8e0"/><circle cx="134" cy="22" r="48" fill="#b8d4c8"/><path d="M19 160c3-44 24-63 61-63s60 19 63 63" fill="#497262"/><path d="M59 92h42v23c-13 11-28 10-42 0z" fill="#dbaa8a"/><ellipse cx="80" cy="64" rx="34" ry="42" fill="#e7bb99"/><path d="M43 69c-7-42 5-61 36-61 40 0 46 31 37 65-4-24-11-38-30-39-10 16-23 21-43 23z" fill="#343d39"/><path d="M67 73h1m24 0h1" stroke="#55534a" stroke-width="4" stroke-linecap="round"/><path d="M72 91q8 5 16 0" fill="none" stroke="#af735c" stroke-width="2.5" stroke-linecap="round"/></svg>');
  const uAttachmentImages=__ATTACHMENT_IMAGE_DATA__;
  const uAttachmentExamples=[{src:uAttachmentImages.payment,title:'付款凭证',type:'支付截图',size:'128 KB'},{src:uAttachmentImages.receipt,title:'午餐小票',type:'票据照片',size:'256 KB'},{src:uAttachmentImages.order,title:'订单详情',type:'订单截图',size:'186 KB'}];
  rSpecs['nickname-edit']={title:'编辑昵称',host:'mine',kind:'dialog'};
  rSpecs['profile-edit']={title:'编辑个人资料',host:'mine',kind:'dialog'};
  rSpecs['attachment-viewer']={title:'附件预览',host:'detail',kind:'viewer'};
  fDefine('nickname-edit','编辑昵称','交互补充','main/mine_page.dart',()=>uNicknameBody());
  fDefine('profile-edit','编辑个人资料','交互补充','main/mine_page.dart',()=>uProfileBody());
  fDefine('attachment-grid','账单详情 · 多张附件','交互补充','../widgets/biz/transaction_list_item.dart',()=>dBillDetail());
  function uLedgerInfo(){const family=state.ledger==='家庭账本',daily=state.ledger==='日常生活',book=state.lBooks?.find(b=>b.name===state.ledger),base={balance:family?23680.8:daily?12860.5:Number(book?.balance||0),records:family?542:daily?1268:Number(book?.count||0),days:family?182:daily?268:0,currency:book?.currency||state.fBaseCurrency},fixtures=family?familyItems:daily?items:[],sign=r=>r.type==='transfer'?0:r.type==='income'?1:-1;let change=0,removed=0;for(const r of fixtures){if(pDeleted.has(r.id)){change-=sign(r)*vNative(r);removed++;}else if(pPatches[r.id]){const next={...r,...pPatches[r.id]};change+=sign(next)*vNative(next)-sign(r)*vNative(r);}}const added=state.additions.filter(r=>r.ledger===state.ledger&&!pDeleted.has(r.id)).map(r=>({...r,...pPatches[r.id]}));change+=added.reduce((sum,r)=>sum+sign(r)*vNative(r),0);return {...base,balance:vRound(base.balance+change),records:base.records+added.length-removed};}
  function uProfileHeader(){const name=state.displayName.trim();return `<div class="bc-profile u-profile">${btn('profile',state.uAvatarImage?`<img src="${esc(state.uAvatarImage)}" alt="自定义头像">`:uProfileBeeMarkup,'编辑头像和资料','bc-avatar u-avatar '+(state.uAvatarImage?'u-avatar-photo':'u-avatar-bee'))}<div class="u-profile-copy"><div class="u-greeting">早上好</div>${btn('u-nickname',`<span class="u-nickname">${esc(name||'设置昵称')}</span>${icon('pencil-line')}`,name?'编辑昵称，当前'+name:'设置昵称','u-name-button')}<div class="bc-small">${name?'简单记录，安心生活':'给自己的账本添一点温度'}</div></div>${btn('profile',icon('chevron-right'),'编辑个人资料','u-profile-next')}</div>`;}
  function uLedgerSummary(){const info=uLedgerInfo();return surface(`<div class="u-ledger-heading">${btn('ledger',`${icon('book-open')}<b>${esc(state.ledger)}</b>${icon('chevron-down')}`,'切换当前账本','u-ledger-switch')}<div class="u-balance-label"><span>${esc(info.currency)}</span>${btn('eye',icon(state.hide?'eye-off':'eye'),state.hide?'显示账本金额':'隐藏账本金额','u-balance-eye')}</div></div><div class="u-ledger-compact"><div class="u-ledger-balance bc-num" data-u-balance ${info.balance<0&&!state.hide?'data-negative="true"':''}><span>${state.hide?'':vSymbol(info.currency)}</span>${shown(info.balance)}</div><div class="u-ledger-meta"><div class="u-ledger-caption">当前余额</div><div class="u-ledger-stats"><div aria-label="已记账${info.days}天"><strong class="bc-num">${info.days}</strong><span>天</span></div><span class="u-stats-dot" aria-hidden="true">·</span>${btn('page:home',`<strong class="bc-num">${info.records.toLocaleString('en-US')}</strong><span>笔</span>`,'查看当前账本'+info.records+'笔账单','')}</div></div></div>`,'u-ledger-summary',true);}
  function uFitProfileMoney(){phone.querySelectorAll('.u-ledger-compact').forEach(row=>{const amount=row.querySelector('.u-ledger-balance'),meta=row.querySelector('.u-ledger-meta');if(!amount||!meta)return;const available=row.clientWidth-meta.getBoundingClientRect().width-8,natural=amount.scrollWidth;if(available>0&&natural>available){const factor=available/natural;amount.style.fontSize=(parseFloat(getComputedStyle(amount).fontSize)*factor)+'px';const prefix=amount.querySelector('span');if(prefix)prefix.style.fontSize=(parseFloat(getComputedStyle(prefix).fontSize)*factor)+'px';}});}
  const uAfterProfileRender=rAfterRender;rAfterRender=function(){uAfterProfileRender();requestAnimationFrame(uFitProfileMoney);};
  function uEnhanceMine(html){const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.bc-profile').outerHTML=uProfileHeader();const stats=t.content.querySelector('.bc-stat-grid');if(stats)stats.closest('.bc-surface').outerHTML=uLedgerSummary();return t.innerHTML;}
  function uNicknameBody(){return `<label class="u-name-field"><span>昵称</span><input data-u-nickname value="${esc(state.uNicknameDraft)}" placeholder="输入你的昵称" maxlength="20" aria-label="昵称" autocomplete="off"><small><span data-u-name-count>${Array.from(state.uNicknameDraft).length}</span> / 20</small></label><p class="p-inline-error" data-u-nickname-error role="alert">${esc(state.uNicknameError)}</p><div class="bc-inline-actions">${btn('r-close','取消','取消修改昵称','bc-secondary')}${btn('u-name-save','保存','保存昵称','bc-primary',state.uNicknameDraft.trim()?'':'disabled')}</div>`;}
  rSpecs['profile-avatar']={title:'选择头像',host:'mine',kind:'dialog'};
  function uAvatarBody(){return `<p class="bc-small">图片只在当前 Demo 本地预览，不上传。</p><label class="u-name-field">${state.uAvatarCapture?'拍摄或选择照片':'选择图片'}<input data-u-avatar-file type="file" accept="image/*" ${state.uAvatarCapture?'capture="user"':''} aria-label="选择头像图片"></label>${btn('u-avatar-example','使用示例图片','使用自定义头像示例','bc-secondary')}${btn('r-close','返回','返回个人资料','bc-secondary')}`;}
  const uPreviousModal=rModalBody;rModalBody=function(key){return key==='profile-avatar'?uAvatarBody():uPreviousModal(key);};
  root.addEventListener('change',e=>{if(!e.target.matches('[data-u-avatar-file]'))return;const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024){notice('请选择5MB以内的图片');e.target.value='';return;}const reader=new FileReader();reader.onload=()=>{state.uAvatarImage=reader.result;if(state.rModal==='profile-avatar')rDismiss();render();notice('头像已在本页预览');};reader.onerror=()=>notice('图片读取失败，请重试');reader.readAsDataURL(file);});
  function uProfileBody(){return `${menuRow('u-nickname','pencil-line','昵称','点击修改',esc(state.displayName||'未设置'))}${menuRow('profile-gallery','images','从相册选择头像')}${menuRow('profile-camera','camera','拍摄头像')}${menuRow('profile-remove','trash-2','恢复默认头像')}`;}
  function uAttachments(r){if(!r?.attachment)return [];return Array.isArray(r.attachments)?r.attachments:state.uAttachmentCount&&r.id===1?uAttachmentExamples.slice(0,state.uAttachmentCount):[uAttachmentExamples[0]];}
  function uAttachmentGrid(r){const images=uAttachments(r);if(!images.length)return '';return surface(`<div class="bc-between"><h3>附件</h3><span class="bc-small">${images.length}张</span></div><div class="u-attachment-grid" data-count="${images.length}">${images.map((a,index)=>btn(`u-attachment:${r.id}:${index}`,`<img src="${a.src}" alt="${esc(a.title)}" loading="eager"><span>${icon('expand')}</span>`,`查看附件${index+1}，${a.title}`,'u-attachment-tile')).join('')}</div>`,'u-attachments');}
  function uEnhanceBillDetail(html){const r=pRows().find(r=>r.id===state.detailId)||pRows()[0]||items[0],t=document.createElement('template');t.innerHTML=html;const hero=t.content.querySelector('.bc-detail-amount')?.parentElement.querySelector('.bc-entry-icon');if(hero)hero.innerHTML=jCategoryVisual(r.subcategory||r.category,r.icon);const legacy=t.content.querySelector('[data-action="attachment-preview"]');if(legacy)legacy.closest('.bc-surface').outerHTML=uAttachmentGrid(r);return t.innerHTML;}
  function uAttachmentViewer(){const r=pRows().find(r=>r.id===state.uAttachmentBill)||items[0],images=uAttachments(r);state.uAttachmentIndex=Math.max(0,Math.min(images.length-1,state.uAttachmentIndex));const a=images[state.uAttachmentIndex];if(!a)return '<div class="p-empty">此账单暂无附件</div>';return `<div class="u-viewer-full"><header class="u-viewer-toolbar">${btn('close',icon('x'),'关闭附件预览')}<div class="u-viewer-title"><span class="u-viewer-filename">${esc(a.title)}</span><span>${state.uAttachmentIndex+1} / ${images.length}</span></div><span class="u-viewer-toolbar-spacer"></span></header><div class="u-attachment-stage" data-u-swipe-viewer><img src="${a.src}" alt="${esc(a.title)}完整图片" draggable="false"></div><footer class="u-viewer-footer"><div class="u-viewer-meta">${esc(a.type)} · ${esc(a.size)}</div>${images.length>1?`<div class="u-viewer-thumbs" aria-label="切换附件">${images.map((image,index)=>btn('u-attachment-select:'+index,`<img src="${image.src}" alt="${esc(image.title)}">`,'查看第'+(index+1)+'张附件','',`aria-pressed="${index===state.uAttachmentIndex}"`)).join('')}</div>`:''}</footer></div>`;}
  root.addEventListener('input',e=>{if(!e.target.matches('[data-u-nickname]'))return;state.uNicknameDraft=e.target.value;const layer=e.target.closest('[role="dialog"]');layer.querySelector('[data-u-name-count]').textContent=Array.from(e.target.value).length;layer.querySelector('[data-action="u-name-save"]').disabled=!e.target.value.trim();layer.querySelector('[data-u-nickname-error]').textContent='';});
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [action,...parts]=el.dataset.action.split(':'),arg=parts.join(':');if(action!=='profile'&&!action.startsWith('u-')&&!['profile-gallery','profile-camera','profile-remove'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();
    if(action==='profile')rOpenModal('profile-edit');
    else if(action==='profile-gallery'||action==='profile-camera'){state.uAvatarCapture=action==='profile-camera';rOpenModal('profile-avatar');}
    else if(action==='profile-remove'){state.uAvatarImage=null;rDismiss();render();notice('已恢复默认蜜蜂头像');}
    else if(action==='u-avatar-example'){state.uAvatarImage=uAvatarExample;rDismiss();render();notice('已使用头像示例');}
    else if(action==='u-nickname'){state.uNicknameDraft=state.displayName;state.uNicknameError='';rOpenModal('nickname-edit');}
    else if(action==='u-name-save'){const name=state.uNicknameDraft.trim();if(!name||Array.from(name).length>20){state.uNicknameError='请输入 1–20 个字的昵称';phone.querySelector('[data-u-nickname-error]').textContent=state.uNicknameError;return;}state.displayName=name;rDismiss();render();notice('昵称已保存');}
    else if(action==='u-attachment'){state.uAttachmentBill=Number(parts[0]);state.uAttachmentIndex=Number(parts[1]);rOpenModal('attachment-viewer');}
    else if(action==='u-attachment-select'){state.uAttachmentIndex=Number(arg);rBuildModal();}
    persist();
  },true);

  // Full-screen preview keeps the original photo browsing path and bill context.
  let uSwipeStart=null;
  root.addEventListener('pointerdown',e=>{if(e.target.closest('[data-u-swipe-viewer]'))uSwipeStart={x:e.clientX,y:e.clientY};});
  root.addEventListener('pointerup',e=>{if(!uSwipeStart)return;const start=uSwipeStart;uSwipeStart=null;if(!e.target.closest('[data-u-swipe-viewer]'))return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)<50||Math.abs(dx)<Math.abs(dy))return;const row=pRows().find(r=>r.id===state.uAttachmentBill)||items[0],images=uAttachments(row);state.uAttachmentIndex=Math.max(0,Math.min(images.length-1,state.uAttachmentIndex+(dx<0?1:-1)));rBuildModal();});
  root.addEventListener('pointercancel',()=>uSwipeStart=null);
